		#region MainTabPage_BindingOrFirstShown

		void MainTabPage_BindingOrFirstShown(object sender, EventArgs e)
		{
			ShowHideControlsBasedOnWarehouseType();
		}

		void ShowHideControlsBasedOnWarehouseType()
		{
			HidePrinterIfNotProductWarehouse();
			HideClientAndDischargeIfNotTransitWarehouse();
		}

		void HidePrinterIfNotProductWarehouse()
		{
			var area = Area;
			if (area != null)
			{
				var warehouse = area.Warehouse;
				var isVisible = warehouse != null && (warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.Product) || warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.FreeTradeZone));
				PickPackPrinterGuidDropEdit.Visible = isVisible;
			}
		}

		void HideClientAndDischargeIfNotTransitWarehouse()
		{
			var area = Area;
			if (!GlbStaff.CurrentUser.IsSupportUser)
			{
				TransitClientGuidFindBox.Visible = false;
			}
			else if (area != null)
			{
				var warehouse = area.Warehouse;

				var isTransit = warehouse != null && warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.Transit);
				var isContainerYard = warehouse != null && warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.ContainerYard);

				var caption = isContainerYard ? Res.GetData("AreaEntryForm|fde0dcbd-43a0-4441-b80a-1522ba30f901", "Container Yard Client") : Res.GetData("AreaEntryForm|8c0869dc-02d1-4d76-b326-4b7810a97ce5", "Transit Warehouse Client");

				TransitClientGuidFindBox.CaptionResourceString = caption;
				TransitClientGuidFindBox.Visible = isTransit || isContainerYard;
			}
		}

		#endregion

		#region OnBindingContextChanged

		protected override void OnBindingContextChanged(EventArgs e)
