		#region Locations Button

		protected void LocationsButton_Click(object sender, EventArgs e)
		{
			WhsArea area = (WhsArea)BusinessEntity;
			if (area.IsInDatabase)
			{
				Controller = ZControllerFactory.Create(ControllerIDs.WhsConfigLocation);
				Controller.SetFormsModalTo(this);
				Controller.ShowEditForm(area);
			}
			else
			{
				Enterprise.ZArchitecture.Environment.Globals.Message.ShowInformation(Res.GetString("5c4790ae-07cf-486d-8277-04522683799f", "This Area must be saved before locations can be edited."), Res.GetString("94c008ac-c5eb-430e-8b79-9d0e2b4b3cad", "Message"));
			}
		}

